import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const out='/tmp/legendgirl-encontros-v9';
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='EASY';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);


 const results=[];
 for(const [name,width,height]of [['desktop',1280,800],['retrato',390,844],['paisagem',844,390]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:name!=='desktop'});await new Promise(r=>setTimeout(r,100));
  const report=await evaluate(`(async()=>{
   const {createGardenState}=await import('/src/js/garden/GardenSimulation.js');const {tickGardenBeetles,tickGardenBee,GARDEN_BEETLES}=await import('/src/js/garden/GardenEncounters.js');
   game.setPaused(true);phase.state=createGardenState('EASY');const s=phase.state;s.stage='RUNNING';Object.assign(s.player,{x:GARDEN_BEETLES[2].x+1,y:590,onGround:true,support:'descanso-final'});tickGardenBeetles(s,0,[]);
   const ctx=phase.canvas.getContext('2d'),draw=ctx.drawImage;let boxes=[];
   ctx.drawImage=function(image,...a){if(image.src?.endsWith('/source/besouro-camadas-v2.png')&&a.length===8){const m=ctx.getTransform(),[x,y,w,h]=a.slice(4),xs=[[x,y],[x+w,y],[x,y+h],[x+w,y+h]].map(([x,y])=>m.a*x+m.c*y+m.e);boxes.push({left:Math.min(...xs),right:Math.max(...xs)});}return draw.call(ctx,image,...a);};
   const frames=[],samples=[];try{for(const age of [0,.15,.35,.65,.85]){s.encounters.panic.elapsed=age;s.encounters.panic.remaining=6-age;boxes=[];const before=JSON.stringify(s);phase.render();if(JSON.stringify(s)!==before)throw Error('Render mudou o domínio');const right=Math.max(...boxes.map(b=>b.right));samples.push({age,right,width:phase.canvas.width});frames.push({label:'besouro-'+age,image:phase.canvas.toDataURL()});}if(samples[0].right>=0)throw Error('Besouro nasceu dentro da tela');if(samples.at(-1).right<0)throw Error('Besouro não entrou pela borda');}finally{ctx.drawImage=draw;}
   phase.state=createGardenState('EASY');const b=phase.state.encounters.bees[0];phase.state.stage='RUNNING';phase.state.player.x=b.x-160;phase.state.player.y=590;b.cooldown=0;tickGardenBee(b,phase.state,.01);tickGardenBee(b,phase.state,.5);const positions=[];
   for(let i=0;i<=20;i++){if(i){phase.state.time+=.125;tickGardenBee(b,phase.state,.125);}if(i===10){positions.push({label:'B',x:b.x,y:b.y,phase:b.phase});const rest={x:b.x,y:b.y};for(let j=0;j<100;j++)tickGardenBee(b,phase.state,1/120);if(b.x!==rest.x||b.y!==rest.y)throw Error('Abelha não ficou parada em B');b.cooldown=0;phase.state.player.x=b.x+100;tickGardenBee(b,phase.state,.01);tickGardenBee(b,phase.state,.5);}if(i===20)positions.push({label:'A',x:b.x,y:b.y,phase:b.phase});phase.render();frames.push({label:'abelha-'+i,image:phase.canvas.toDataURL()});}
   window.encounterFrames=frames;return{format:'${name}',samples,positions};
  })()`);
  results.push(report);const frames=await evaluate('encounterFrames');
  for(const f of frames)await writeFile(out+'/'+name+'-'+f.label+'.png',Buffer.from(f.image.split(',')[1],'base64'));
 }
 await writeFile('docs/diario-ia/qa-resultados/yuna/encontros-v9.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
